insert into public.categories (id, name) values ('wedding', 'Wedding') on conflict (id) do nothing;
insert into public.templates (id, category_id, name, html_code) values ('classic', 'wedding', 'Classic Floral', '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;background:#f7efe5;color:#44372d;font-family:Georgia,serif}.card{max-width:620px;min-height:100vh;margin:auto;padding:55px 28px;text-align:center;background:#fffaf2}.eyebrow{font:11px Arial;letter-spacing:4px;color:#a17d54}.flower{font-size:42px;margin:25px}.names{font-size:42px;line-height:1.3;margin:25px 0}.detail{font:14px/2 Arial;color:#77695d;margin:18px}.rule{width:80px;border-top:1px solid #c8ad8d;margin:25px auto}</style></head><body><main class="card"><div class="eyebrow">WITH THE BLESSINGS OF OUR FAMILIES</div><div class="flower">❀</div><div class="eyebrow">CORDIALLY INVITE YOU TO CELEBRATE</div><div class="names">{{groom-en}}<br>&amp;<br>{{bride-en}}</div><div class="rule"></div><div class="eyebrow">ON {{event-wedding-day}}</div><div class="detail">{{event-wedding-date}} · {{event-wedding-time}}<br>{{venue-en}}<br>{{venue-address}}</div><div class="rule"></div><div class="eyebrow">YOUR PRESENCE IS OUR GREATEST GIFT</div></main></body></html>') on conflict (id) do nothing;
insert into public.templates (id, category_id, name, html_code) values ('modern', 'wedding', 'Modern Minimal', '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>*{box-sizing:border-box}body{margin:0;background:#e9ece8;color:#202a25;font-family:Arial,sans-serif}.card{max-width:620px;min-height:100vh;margin:auto;padding:65px 34px;background:#fbfcf8;text-align:center;display:flex;flex-direction:column;justify-content:center}.eyebrow{font-size:10px;letter-spacing:5px;color:#78867b}.names{font:48px/1.3 Georgia,serif;margin:40px 0}.amp{font-size:25px;color:#8d9a8d}.rule{height:1px;background:#cbd2ca;width:70px;margin:22px auto}.detail{font-size:14px;line-height:2;color:#58645b}.venue{font:22px Georgia,serif;margin:25px 0 8px}</style></head><body><main class="card"><div class="eyebrow">SAVE THE DATE</div><div class="names">{{groom-en}}<br><span class="amp">&amp;</span><br>{{bride-en}}</div><div class="rule"></div><div class="eyebrow">ARE GETTING MARRIED</div><p class="detail">{{event-wedding-day}}<br>{{event-wedding-date}} · {{event-wedding-time}}</p><div class="venue">{{venue-en}}</div><div class="detail">{{venue-address}}</div></main></body></html>') on conflict (id) do nothing;
